-- All fixtures run under a SAVEPOINT and are rolled back, including auth rows.
create temporary table b2b_fixture_keys(k text primary key,v uuid);
grant select on b2b_fixture_keys to authenticated;
do $$
declare owner_id uuid:=gen_random_uuid();finance_id uuid:=gen_random_uuid();coordinator_id uuid:=gen_random_uuid();outsider_id uuid:=gen_random_uuid();admin_id uuid:=gen_random_uuid();
 company_a uuid:=gen_random_uuid();company_b uuid:=gen_random_uuid();trip_id uuid:=gen_random_uuid();attempt_id uuid:=gen_random_uuid();request_id uuid;invitation_id uuid;application_id uuid;new_company uuid;
 plan_id text;payload jsonb;failure text;workspace jsonb;extra_trip uuid;factor_id uuid:=gen_random_uuid();plan_days integer;legacy_invitation uuid;
begin
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
 (owner_id,owner_id::text||'@example.invalid',now(),'{}'),(finance_id,finance_id::text||'@example.invalid',now(),'{}'),(coordinator_id,coordinator_id::text||'@example.invalid',now(),'{}'),(outsider_id,outsider_id::text||'@example.invalid',now(),'{}'),(admin_id,admin_id::text||'@example.invalid',now(),'{}');
 insert into public.admin_memberships(user_id) values(admin_id);
 insert into public.b2b_organizations(id,name) values(company_a,'Synthetic company A'),(company_b,'Synthetic company B');
 insert into public.b2b_memberships(company_id,user_id,role) values(company_a,owner_id,'owner'),(company_a,coordinator_id,'coordinator'),(company_b,outsider_id,'owner');
 insert into b2b_fixture_keys values('coordinator',coordinator_id),('company_a',company_a),('company_b',company_b),('trip',trip_id);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal1')::text,true);
 if public.b2b_role(company_a)<>'owner' or public.b2b_role(company_b) is not null then raise exception 'isolation_failed';end if;
 invitation_id:=public.b2b_invite(company_a,finance_id::text||'@example.invalid','finance');
 if invitation_id is distinct from public.b2b_invite(company_a,finance_id::text||'@example.invalid','finance') then raise exception 'invitation_idempotency';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider_id,'role','authenticated')::text,true);
 failure:=null;begin perform public.b2b_accept_invitation(invitation_id);exception when others then failure:=sqlerrm;end;if failure is distinct from 'invitation_unavailable' then raise exception 'wrong_recipient_accepted';end if;
 failure:=null;begin perform public.b2b_workspace(company_a);exception when others then failure:=sqlerrm;end;if failure is distinct from 'company_required' then raise exception 'cross_company_read';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',finance_id,'role','authenticated','user_metadata',jsonb_build_object('role','owner'))::text,true);
 perform public.b2b_accept_invitation(invitation_id);
 if public.b2b_role(company_a)<>'finance' then raise exception 'invitation_role';end if;
 payload:=jsonb_build_object('name','Europe group','destination','japan','departure','2026-12-20','returning','2026-12-26','travelers',30,'mode','package');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider_id,'role','authenticated')::text,true);
 perform public.b2b_create_trip(company_b,gen_random_uuid(),payload);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',finance_id,'role','authenticated','user_metadata',jsonb_build_object('role','owner'))::text,true);
 failure:=null;begin perform public.b2b_create_trip(company_a,trip_id,payload);exception when others then failure:=sqlerrm;end;if failure is distinct from 'role_required' then raise exception 'finance_can_create';end if;
 failure:=null;begin perform public.b2b_invite(company_a,'other@example.invalid','owner');exception when others then failure:=sqlerrm;end;if failure is distinct from 'role_required' then raise exception 'finance_can_invite';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coordinator_id,'role','authenticated')::text,true);
 perform public.b2b_create_trip(company_a,trip_id,payload);perform public.b2b_create_trip(company_a,trip_id,payload);
 if(select count(*) from public.b2b_trips where id=trip_id)<>1 then raise exception 'duplicate_trip';end if;
 failure:=null;begin perform public.b2b_create_trip(company_b,gen_random_uuid(),payload);exception when others then failure:=sqlerrm;end;if failure is distinct from 'company_required' then raise exception 'cross_company_write';end if;
 failure:=null;begin perform public.b2b_create_trip(company_a,trip_id,payload||'{"travelers":29}');exception when others then failure:=sqlerrm;end;if failure is distinct from 'conflict' then raise exception 'trip_replay_conflict';end if;
 select p->>'id' into plan_id from jsonb_array_elements(public.b2b_catalog(company_a,'japan')) p where(p->>'days')::integer>=7 limit 1;
 if plan_id is null then raise exception 'test_catalog_empty';end if;
 failure:=null;begin perform public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,30,null);exception when others then failure:=sqlerrm;end;if failure is distinct from 'conflict' then raise exception 'null_version_bypass';end if;
 select days into plan_days from public.catalog_plans where id=plan_id;
 extra_trip:=gen_random_uuid();
 perform public.b2b_create_trip(company_a,extra_trip,payload||jsonb_build_object('returning',('2026-12-20'::date+plan_days)::text));
 failure:=null;begin perform public.b2b_submit_request(company_a,extra_trip,gen_random_uuid(),plan_id,30,1);exception when others then failure:=sqlerrm;end;if failure is distinct from 'plan_too_short' then raise exception 'duration_guard';end if;
 delete from public.b2b_trips where id=extra_trip;
 extra_trip:=gen_random_uuid();
 perform public.b2b_create_trip(company_a,extra_trip,payload||'{"mode":"individual"}');
 perform public.b2b_submit_request(company_a,extra_trip,gen_random_uuid(),plan_id,25,1);
 delete from public.b2b_order_requests r where r.trip_id=extra_trip;delete from public.b2b_trips where id=extra_trip;
 failure:=null;begin perform public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,29,1);exception when others then failure:=sqlerrm;end;if failure is distinct from 'invalid_quantity' then raise exception 'partial_package';end if;
 failure:=null;begin perform public.b2b_submit_request(company_a,trip_id,attempt_id,'not-a-real-plan',30,1);exception when others then failure:=sqlerrm;end;if failure is distinct from 'plan_unavailable' then raise exception 'unknown_plan';end if;
 request_id:=public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,30,1);
 if request_id is distinct from public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,30,1) then raise exception 'duplicate_request';end if;
 failure:=null;begin perform public.b2b_submit_request(company_a,trip_id,gen_random_uuid(),plan_id,30,1);exception when others then failure:=sqlerrm;end;if failure is distinct from 'conflict' then raise exception 'stale_trip_write';end if;
 failure:=null;begin perform public.b2b_admin_action(outsider_id,'review_request',jsonb_build_object('id',request_id,'version',1,'decision','approved','note',''));exception when others then failure:=sqlerrm;end;if failure is distinct from 'admin_required' then raise exception 'outsider_admin';end if;
 perform public.b2b_admin_action(admin_id,'review_request',jsonb_build_object('id',request_id,'version',1,'decision','changes','note','Please review the group.'));
 failure:=null;begin perform public.b2b_admin_action(admin_id,'review_request',jsonb_build_object('id',request_id,'version',1,'decision','approved','note',''));exception when others then failure:=sqlerrm;end;if failure is distinct from 'conflict' then raise exception 'stale_admin_review';end if;
 perform public.b2b_submit_request(company_a,trip_id,gen_random_uuid(),plan_id,30,3);
 perform public.b2b_admin_action(admin_id,'review_request',jsonb_build_object('id',request_id,'version',3,'decision','approved','note','Commercial review only.'));
 workspace:=public.b2b_workspace(company_a);
 if workspace->'company'->>'role'<>'coordinator' or jsonb_array_length(workspace->'members')<>0 or workspace->'trips'->0->'request'->>'status'<>'approved' then raise exception 'workspace_projection';end if;
 perform public.b2b_admin_action(admin_id,'company_status',jsonb_build_object('id',company_a,'status','suspended','note','Synthetic suspension'));
 failure:=null;begin perform public.b2b_workspace(company_a);exception when others then failure:=sqlerrm;end;if failure is distinct from 'company_required' then raise exception 'suspended_company_access';end if;
 perform public.b2b_admin_action(admin_id,'company_status',jsonb_build_object('id',company_a,'status','active','note','Synthetic restore'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
 failure:=null;begin perform public.b2b_invite(company_a,finance_id::text||'@example.invalid','coordinator');exception when others then failure:=sqlerrm;end;if failure is distinct from 'invalid_state' then raise exception 'existing_member_invitation';end if;
 insert into public.b2b_invitations(company_id,email,role,created_by) values(company_a,finance_id::text||'@example.invalid','finance',owner_id) returning id into legacy_invitation;
 perform public.b2b_remove_member(company_a,finance_id);
 if(select status from public.b2b_invitations where id=legacy_invitation)<>'revoked' then raise exception 'pending_invitation_survives_removal';end if;
 invitation_id:=public.b2b_invite(company_a,finance_id::text||'@example.invalid','finance');
 update public.b2b_invitations set expires_at=now()-interval '1 second' where id=invitation_id;
 failure:=null;begin perform public.b2b_remove_member(company_a,owner_id);exception when others then failure:=sqlerrm;end;if failure is distinct from 'role_required' then raise exception 'owner_removal';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',finance_id,'role','authenticated')::text,true);
 failure:=null;begin perform public.b2b_accept_invitation(legacy_invitation);exception when others then failure:=sqlerrm;end;if failure is distinct from 'invitation_unavailable' then raise exception 'removed_member_can_rejoin';end if;
 failure:=null;begin perform public.b2b_accept_invitation(invitation_id);exception when others then failure:=sqlerrm;end;if failure is distinct from 'invitation_unavailable' then raise exception 'expired_invitation';end if;
 invitation_id:=(select id from public.b2b_invitations where company_id=company_a and status='accepted' limit 1);
 failure:=null;begin perform public.b2b_accept_invitation(invitation_id);exception when others then failure:=sqlerrm;end;if failure is distinct from 'invitation_unavailable' then raise exception 'revoked_membership_resurrection';end if;
 application_id:=public.b2b_apply('Synthetic application','','');
 new_company:=public.b2b_admin_action(admin_id,'approve_application',jsonb_build_object('id',application_id,'note','Synthetic approval'));
 if new_company is distinct from public.b2b_admin_action(admin_id,'approve_application',jsonb_build_object('id',application_id,'note','retry')) then raise exception 'duplicate_company';end if;
 if public.b2b_role(new_company)<>'owner' then raise exception 'application_owner';end if;
 insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values(factor_id,owner_id,'totp','verified','synthetic-only',now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal1')::text,true);
 failure:=null;begin perform public.b2b_workspace(company_a);exception when others then failure:=sqlerrm;end;if failure is distinct from 'mfa_required' then raise exception 'mfa_bypass';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal2')::text,true);
 perform public.b2b_workspace(company_a);delete from auth.mfa_factors where id=factor_id;
 perform set_config('request.jwt.claims','{}',true);
 failure:=null;begin perform public.b2b_workspace(null);exception when others then failure:=sqlerrm;end;if failure is distinct from 'verified_account_required' then raise exception 'anonymous_rpc';end if;
end;$$;

set local role authenticated;
do $$declare n integer;failure text;
begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',(select v from b2b_fixture_keys where k='coordinator'),'role','authenticated')::text,true);
 select count(*) into n from public.b2b_trips;
 if n<>1 then raise exception 'RLS_trip_visibility';end if;
 select count(*) into n from public.b2b_organizations where id=(select v from b2b_fixture_keys where k='company_b');
 if n<>0 then raise exception 'RLS_company_visibility';end if;
 failure:=null;begin update public.b2b_trips set travelers=100 where id=(select v from b2b_fixture_keys where k='trip');exception when insufficient_privilege then failure:='denied';end;if failure is distinct from 'denied' then raise exception 'direct_mutation_allowed';end if;
 failure:=null;begin perform public.b2b_admin_records((select v from b2b_fixture_keys where k='coordinator'));exception when insufficient_privilege then failure:='denied';end;if failure is distinct from 'denied' then raise exception 'admin_rpc_public';end if;
end;$$;
reset role;
